import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import {useCallback, useEffect, useState} from 'react'

import {
  CUSTOM_EVENTS,
  DEFAULT_EVENTS,
} from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineNotifications/PipelineNotifications.const'
import {usePipelineId} from '../../hooks/pipeline'
import {pipelinesApi} from '../../services/pipelinesApi'
import type {Event, PersonalNotificationsDto} from '../../services/pipelinesApi.types'

export function isSubscribed(notifications: PersonalNotificationsDto | undefined) {
  if (!notifications) {
    return false
  }

  return (
    notifications.events.filter(event =>
      DEFAULT_EVENTS.find(e => event.type === e.type && event.enabled),
    ).length > 0
  )
}
function hasCustomNotifications(notifications: PersonalNotificationsDto | undefined) {
  if (!notifications) {
    return undefined
  }
  if (notifications.events.find(event => event.enabled) === undefined) {
    return undefined
  }
  return notifications.events.some(
    event =>
      DEFAULT_EVENTS.find(e => e.type === event.type && e.enabled !== event.enabled) ||
      !notifications.ownChangesOnly,
  )
}

export const useNotificationsButtonLogic = () => {
  const pipelineId = usePipelineId()
  const {
    data: notifications,
    isLoading,
    error,
  } = pipelinesApi.endpoints.getPersonalNotifications.useQuery({
    pipelineId,
  })
  useEffect(() => {
    if (error) {
      alertService.error('Could not fetch personal notifications')
    }
  }, [error])
  const [ownChangesOnly, setOwnChangesOnly] = useState(notifications?.ownChangesOnly ?? false)
  const [isCustomNotifications, setIsCustomNotifications] = useState<boolean | undefined>(false)
  const [customEvents, setCustomEvents] = useState<Event[]>(
    hasCustomNotifications(notifications) ? notifications!.events : [...CUSTOM_EVENTS],
  )
  useEffect(() => {
    const isCustom = hasCustomNotifications(notifications)
    setIsCustomNotifications(isCustom)
    if (isCustom && notifications) {
      setCustomEvents(
        notifications.events.filter(event => DEFAULT_EVENTS.find(e => e.type === event.type)),
      )
    } else {
      setCustomEvents([...CUSTOM_EVENTS])
    }
  }, [notifications])

  const [setPersonalaNotifications] = pipelinesApi.endpoints.setPersonalNotifications.useMutation()

  const submitChanges = useCallback(
    async (newEvents: Event[], ownChanges: boolean) => {
      try {
        await setPersonalaNotifications({
          pipelineId,
          notifications: {ownChangesOnly: ownChanges, events: newEvents},
        })
      } catch (_) {
        alertService.error('Could not update personal notifications')
      }
    },
    [pipelineId, setPersonalaNotifications],
  )

  return {
    notifications,
    submitChanges,
    ownChangesOnly,
    setOwnChangesOnly,
    isCustomNotifications,
    setIsCustomNotifications,
    customEvents,
    setCustomEvents,
    isLoading,
  }
}
