import {withProps} from 'recompose'

import compose from 'lodash/flowRight'

import {withProjectOrBuildTypeNode} from '../../../hooks/routes'

import OverviewStatusIcon from './OverviewStatusIcon.container'
import type {
  OverviewHeaderIconAddProps,
  OverviewHeaderIconOwnProps,
} from './ProjectOrBuildTypeIcon.types'
import {EntityIconType} from './ProjectOrBuildTypeIcon.types'

export default compose(
  withProjectOrBuildTypeNode,
  withProps(({projectOrBuildTypeNode}: OverviewHeaderIconOwnProps): OverviewHeaderIconAddProps => {
    if (projectOrBuildTypeNode == null) {
      return {type: null}
    }
    switch (projectOrBuildTypeNode.nodeType) {
      case 'project':
        return {type: EntityIconType.PROJECT, id: projectOrBuildTypeNode.id}
      case 'bt':
        return {type: EntityIconType.BUILD_TYPE, id: projectOrBuildTypeNode.id}
      case 'pipeline':
        return {type: EntityIconType.PIPELINE, id: projectOrBuildTypeNode.id}
      default:
        return {type: null}
    }
  }),
)(OverviewStatusIcon)
