import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Content from '@jetbrains/ring-ui-built/components/island/content'
import Header from '@jetbrains/ring-ui-built/components/island/header'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import {useNavigate} from 'react-router'

import {getAddRepositoryHref} from '../../../../../routes'
import type {PipelineId} from '../../../../../types'
import usePermissionCanEditPipeline from '../../hooks/usePermissionCanEditPipeline'

import {
  addRepositoryMessage,
  addRepositoryNoPermissionsMessage,
} from './RepositoryRequiredDialog.consts'

type Props = {
  pipelineId?: PipelineId
  show?: boolean
  redirectTo?: string
  onClose?: () => void
}
function RepositoryRequiredDialog({pipelineId, show, redirectTo, onClose}: Props) {
  const navigate = useNavigate()
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const onClick =
    pipelineId != null
      ? () => navigate(getAddRepositoryHref(pipelineId), {state: {redirectTo}})
      : undefined
  return (
    <Dialog
      show={show}
      onCloseAttempt={onClose}
      onCloseClick={onClose}
      closeButtonInside
      showCloseButton
    >
      <Header>{'Specify the repository'}</Header>
      <Content>
        {canEditPipeline ? addRepositoryMessage : addRepositoryNoPermissionsMessage}
      </Content>
      <Panel>
        {canEditPipeline ? (
          <ButtonSet>
            <Button primary onClick={onClick}>
              {'Add repository'}
            </Button>
            <Button onClick={onClose}>{'Cancel'}</Button>
          </ButtonSet>
        ) : (
          <Button primary onClick={onClose}>
            {'Got it'}
          </Button>
        )}
      </Panel>
    </Dialog>
  )
}
export default RepositoryRequiredDialog
