import exceptionIcon from '@jetbrains/icons/exception.svg'
import lockIcon from '@jetbrains/icons/lock.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import {Suspense} from 'react'
import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer, usePreloadedQuery} from 'react-relay'

import {useBooleanQueryParam} from '../../../../hooks/routes'
import {getPipelinesHref} from '../../../../routes'
import Loader from '../../../common/Loader/Loader'
import RouterLink from '../../../common/RouterLink/RouterLink'
import type {PipelinesPagesQuery} from '../__generated__/PipelinesPagesQuery.graphql'
import FullScreenErrorWrapper from '../components/FullScreenErrorWrapper/FullScreenErrorWrapper'
import type {EditPipelinePageEntryPoint} from '../EditPipelinePage/EditPipelinePage.entryPoint'
import {usePipelineId} from '../hooks/pipeline'
import usePermissionCanEditPipeline from '../hooks/usePermissionCanEditPipeline'
import {pipelineQuery} from '../PipelinesPages.queries'
import {pipelinesApi} from '../services/pipelinesApi'
import {serializeError} from '../utils/error'

import type {PipelineContentEntryPoint} from './PipelineContent/PipelineContent.entryPoint'
import PipelineHeader from './PipelineHeader/PipelineHeader'

import styles from './PipelinePage.module.css'

type Queries = {pipelineHead: PipelinesPagesQuery}
export type NestedEntryPoints = {
  pipelineContent?: typeof PipelineContentEntryPoint
  editPipelineContent?: typeof EditPipelinePageEntryPoint
}
type Props = EntryPointProps<Queries, NestedEntryPoints, {}, {}>
function PipelinePage({queries, entryPoints}: Props) {
  const {headBuildType: pipelineHeadBuildTypeKey = null} =
    usePreloadedQuery(pipelineQuery, queries.pipelineHead)?.pipeline ?? {}
  const id = usePipelineId()
  const {isLoading, pipelineError} = pipelinesApi.endpoints.getPipelineById.useQuery(id, {
    selectFromResult: ({isLoading, error}) => ({
      isLoading,
      pipelineError: error,
    }),
  })
  const isEdit = useBooleanQueryParam('edit')
  const {canViewPipelineSettings} = usePermissionCanEditPipeline()

  if (isEdit && !canViewPipelineSettings) {
    return (
      <FullScreenErrorWrapper>
        <ErrorMessage
          icon={lockIcon}
          message="Access denied"
          description="You do not have enough permissions to view this pipeline's settings"
        >
          <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
        </ErrorMessage>
      </FullScreenErrorWrapper>
    )
  }

  if (isLoading) {
    return <Loader />
  }

  if (pipelineError) {
    return (
      <FullScreenErrorWrapper>
        <ErrorMessage
          icon={exceptionIcon}
          message="Error while loading pipeline"
          description={serializeError(pipelineError)}
        >
          <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
        </ErrorMessage>
      </FullScreenErrorWrapper>
    )
  }

  return (
    <>
      <PipelineHeader pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
      <Suspense fallback={<Loader />}>
        {!isEdit && entryPoints.pipelineContent ? (
          <div className={styles.contentContainer}>
            <EntryPointContainer
              entryPointReference={entryPoints.pipelineContent}
              props={{pipelineHeadBuildTypeKey}}
            />
          </div>
        ) : null}
        {isEdit && entryPoints.editPipelineContent ? (
          <EntryPointContainer entryPointReference={entryPoints.editPipelineContent} props={{}} />
        ) : null}
      </Suspense>
    </>
  )
}

export default function PipelinePageContainer(props: Props) {
  return (
    <div className={styles.page}>
      <Suspense fallback={<Loader className={styles.header} />}>
        <PipelinePage {...props} />
      </Suspense>
    </div>
  )
}

export type PipelinePageComponent = typeof PipelinePage
