import {objectValues} from '@jetbrains/teamcity-ui/dist/utils'
import {Suspense, useEffect, useMemo, useState} from 'react'
import {useQueryLoader} from 'react-relay'
import {useLocation} from 'react-router'

import {useBooleanQueryParam, useBranch} from '../../../../../hooks/routes'
import {Policy} from '../../../../../rest/branches'
import {getBuildTypeFilter} from '../../../../../types'
import {DEFAULT_NAME} from '../../../../../utils/branchNames'
import {TimeBadge} from '../../../../common/Badges'
import {useHasRuns, useOptimizations} from '../../../../common/Badges/TimeBadge/TimeBadge.hooks'
import type {BranchSelectBranchesQuery} from '../../../../common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import {
  branchesQuery,
  getBranchesQueryVariables,
} from '../../../../common/BranchSelect/BranchSelect.queries'
import OverviewHeaderIcon from '../../../../common/ProjectOrBuildTypeIcon/OverviewHeaderIcon.container'
import RunButton from '../../../../common/RunPipelineButton/RunPipelineButton'
import {BranchBadge, RepositoryBadge, PipelineSystemProblemsBadge} from '../../components/Badges'
import Header from '../../components/Header/Header'
import NotificationsButton from '../../components/NotificationsButton/NotificationsButton'
import RepositoryRequiredDialog from '../../components/RepositoryRequiredDialog/RepositoryRequiredDialog'
import type {pipelineHeadBuildTypeFragment$key} from '../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineHead, usePipelineId} from '../../hooks/pipeline'
import useBooleanState from '../../hooks/useBooleanState'
import {pipelinesApi} from '../../services/pipelinesApi'
import {VcsProviderType} from '../../services/pipelinesApi.types'
import {isNotificationsFeatureEnabled} from '../../utils/featureToggles'
import {getRepositoryNameFromVcsRoot} from '../../utils/vcs'

import styles from './PipelineHeader.module.css'

type Props = {
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}
export default function PipelineHeader({pipelineHeadBuildTypeKey}: Props) {
  const id = usePipelineId()
  const location = useLocation()
  const isVcsEmpty = location.state?.isVcsEmpty ?? false
  const {name, parallelized, vcsRoot, additionalVcsRoots} =
    pipelinesApi.endpoints.getPipelineById.useQuery(id, {
      selectFromResult: ({data}) => {
        const {settings, name, vcsRoot, additionalVcsRoots} = data ?? {}
        return {
          name,
          vcsRoot,
          additionalVcsRoots,
          parallelized: settings?.jobs
            ? objectValues(settings?.jobs).some(({parallelism}) => !!parallelism)
            : null,
        }
      },
      refetchOnMountOrArgChange: true,
    })
  const head = usePipelineHead(pipelineHeadBuildTypeKey)
  const [branchesQueryRef, loadBranches] = useQueryLoader<BranchSelectBranchesQuery>(branchesQuery)
  useEffect(() => {
    if (head?.id != null) {
      loadBranches(
        getBranchesQueryVariables({
          node: getBuildTypeFilter(head.id),
          policy: Policy.ALL_BRANCHES,
        }),
      )
    }
  }, [head?.id, loadBranches])
  const branch = useBranch()
  const defaultBranch = branch?.default || branch?.groupFlag
  const branchName = defaultBranch ? DEFAULT_NAME : branch?.name
  const isEdit = useBooleanQueryParam('edit')

  const mainRepo = useMemo(
    () =>
      vcsRoot != null
        ? {
            name: getRepositoryNameFromVcsRoot(vcsRoot, true),
            vcsProviderType: vcsRoot.isExternal
              ? VcsProviderType.EXISTING_VCS_ROOT
              : vcsRoot.vcsProviderType,
          }
        : null,
    [vcsRoot],
  )
  const additionalRepos = useMemo(
    () =>
      additionalVcsRoots?.map(additionalVcsRoot => getRepositoryNameFromVcsRoot(additionalVcsRoot)),
    [additionalVcsRoots],
  )
  const hasVcsRoot = mainRepo != null
  const [
    repositoryRequiredDialogShown,
    showRepositoryRequiredDialog,
    closeRepositoryRequiredDialog,
  ] = useBooleanState(false)
  const [redirectTo, setRedirectTo] = useState<string | undefined>()
  const onShowRepositoryRequiredDialog = (to?: string) => {
    setRedirectTo(to)
    showRepositoryRequiredDialog()
  }

  const {data, isLoading} = pipelinesApi.endpoints.getPipelineOptimizations.useQuery(
    {pipelineId: id, branch: branchName ?? ''},
    {
      selectFromResult: ({data, isLoading}) => ({
        data,
        isLoading,
      }),
    },
  )

  const {totalDuration, optimizedDuration, optimizations: appliedOptimizations, runs} = data ?? {}
  const hasRuns = useHasRuns(pipelineHeadBuildTypeKey)

  const duration = Number(totalDuration)
  const optimized = Number(optimizedDuration)

  const {optimizations, possibleOptimizations} = useOptimizations(
    appliedOptimizations,
    parallelized,
  )

  useEffect(() => {
    if (isVcsEmpty && !hasVcsRoot) {
      showRepositoryRequiredDialog()
    }
  }, [hasVcsRoot, isVcsEmpty, showRepositoryRequiredDialog])

  const badges = useMemo(
    () => (
      <Suspense>
        {hasVcsRoot && <BranchBadge headId={head?.id} branchesQueryRef={branchesQueryRef} />}
        <TimeBadge
          popupClassName={styles.timeBadge}
          duration={duration}
          optimizedDuration={optimized}
          withAppliedOptimizations={!!optimizations?.length}
          isLoading={isLoading}
          optimizations={optimizations}
          possibleOptimizations={possibleOptimizations}
          popupTitle={hasRuns ? 'Run duration for the last 10 runs' : null}
          runs={runs}
          hasNoRuns={!hasRuns}
        />
        <RepositoryBadge
          displayedRepo={mainRepo?.name}
          vcsProviderType={mainRepo?.vcsProviderType}
          additionalRepos={additionalRepos}
        />
        <PipelineSystemProblemsBadge pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
      </Suspense>
    ),
    [
      hasVcsRoot,
      head?.id,
      branchesQueryRef,
      duration,
      optimized,
      optimizations,
      isLoading,
      possibleOptimizations,
      hasRuns,
      runs,
      mainRepo?.name,
      mainRepo?.vcsProviderType,
      additionalRepos,
      pipelineHeadBuildTypeKey,
    ],
  )

  return (
    <>
      <Header
        className={!isEdit ? styles.header : null}
        pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
        icon={<OverviewHeaderIcon size="L" />}
        title={name}
        contentClassName={styles.badges}
        hasVcsRoot={hasVcsRoot}
        showRepositoryRequiredDialog={onShowRepositoryRequiredDialog}
        content={badges}
        actions={
          <>
            {isNotificationsFeatureEnabled && <NotificationsButton pipelineId={id} />}
            <RunButton
              primary
              headId={head?.id}
              projectId={head?.projectId}
              className={styles.button}
              branchName={branch?.default ? undefined : branch?.name}
              hasVcsRoot={hasVcsRoot}
              showRepositoryRequiredDialog={showRepositoryRequiredDialog}
            />
          </>
        }
        showBottomBorder
      />
      <RepositoryRequiredDialog
        pipelineId={id}
        show={repositoryRequiredDialogShown}
        redirectTo={redirectTo}
        onClose={closeRepositoryRequiredDialog}
      />
    </>
  )
}
