import type {ButtonAttrs} from '@jetbrains/ring-ui-built/components/button/button'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {Type} from '@jetbrains/ring-ui-built/components/list/consts'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import cn from 'classnames'
import {memo, useEffect, useState} from 'react'

import useMyId from '../../../../../hooks/useMyId'
import type {PipelineId} from '../../../../../types'
import {GUEST_ID, SUPER_USER_ID} from '../../../../../types'
import Icon from '../../../../common/Icon/Icon'
import Popup from '../../../../common/Popup/Popup.lazy'
import CustomNotificationEvents from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineNotifications/editor/CustomNotificationEvents/CustomNotificationEvents'
import {DEFAULT_EVENTS} from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineNotifications/PipelineNotifications.const'
import type {Event} from '../../services/pipelinesApi.types'

import {isSubscribed, useNotificationsButtonLogic} from './NotificationsButton.hooks'

import styles from './NotificationsButton.module.css'

type Props = ButtonAttrs & {
  pipelineId: PipelineId
}

export default function NotificationsButton({pipelineId}: Props) {
  const {
    notifications,
    submitChanges,
    ownChangesOnly,
    setOwnChangesOnly,
    isCustomNotifications,
    setIsCustomNotifications,
    customEvents,
    setCustomEvents,
    isLoading,
  } = useNotificationsButtonLogic()
  const [customNotificationEventsLocal, setCustomNotificationEventLocal] =
    useState<Event[]>(customEvents)
  const [ownChangesOnlyLocal, setOwnChangesOnlyLocal] = useState<boolean>(ownChangesOnly)

  useEffect(() => {
    setCustomNotificationEventLocal(customEvents)
  }, [customEvents])

  useEffect(() => {
    setOwnChangesOnlyLocal(ownChangesOnly)
  }, [ownChangesOnly])

  const myId = useMyId()
  const isSpecialUser = myId === GUEST_ID || myId === SUPER_USER_ID
  const SubscribeButton = memo(({onClick}: {onClick?: () => Promise<void>}) => (
    <Button
      disabled={isSpecialUser}
      height={ControlsHeight.M}
      primary={false}
      loader={isLoading}
      dropdown={isSubscribed(notifications)}
      onClick={onClick}
    >
      {isSubscribed(notifications) && <Icon className={styles.icon} name={'bell'} />}
      {isSubscribed(notifications) ? 'Subscribed' : 'Subscribe'}
    </Button>
  ))
  SubscribeButton.displayName = 'SubscribeButton'

  return (
    <>
      {isSubscribed(notifications) ? (
        <Dropdown anchor={<SubscribeButton />}>
          <Popup
            directions={[Directions.BOTTOM_LEFT]}
            offset={4}
            onCloseAttempt={() => {}}
            onOutsideClick={async () => {
              if (isCustomNotifications) {
                setCustomEvents(customNotificationEventsLocal)
                setOwnChangesOnly(ownChangesOnlyLocal)
                await submitChanges(customNotificationEventsLocal, ownChangesOnlyLocal)
              }
            }}
          >
            <>
              <List
                shortcuts
                activateFirstItem
                data={[
                  {
                    template: (
                      <div className={styles.popupLine}>
                        <Icon
                          className={cn(styles.icon, {
                            [styles.invisible]:
                              isCustomNotifications === undefined || isCustomNotifications,
                          })}
                          name={'checkmark'}
                        />
                        <div className={styles.popupLineText}>
                          <Text>{'Default email notifications'}</Text>
                          <Text info size={'s'}>
                            {'Notify me when builds with my changes fail'}
                          </Text>
                        </div>
                      </div>
                    ),
                    rgItemType: Type.CUSTOM,
                    onClick: async () => {
                      setIsCustomNotifications(false)
                      await submitChanges(DEFAULT_EVENTS, true)
                    },
                    key: 'default',
                  },
                  {
                    template: (
                      <div className={styles.popupLine}>
                        <Icon
                          className={cn(styles.icon, {
                            [styles.invisible]:
                              isCustomNotifications === undefined || !isCustomNotifications,
                          })}
                          name={'checkmark'}
                        />
                        <div className={styles.popupLineText}>
                          <Text>{'Custom notifications'}</Text>
                          <Text size={'s'} info>
                            {'Choose which event notifications to receive'}
                          </Text>
                          {isCustomNotifications && (
                            <>
                              {' '}
                              <Toggle
                                checked={ownChangesOnlyLocal}
                                onChange={_ => {
                                  const newValue = !ownChangesOnlyLocal
                                  setOwnChangesOnlyLocal(newValue)
                                }}
                                className={styles.toggleOffset}
                              >
                                {'Only with my changes'}
                              </Toggle>
                              <CustomNotificationEvents
                                events={customNotificationEventsLocal.filter(event =>
                                  DEFAULT_EVENTS.find(e => e.type === event.type),
                                )}
                                updateEvents={(newEvents: Event[]) => {
                                  setCustomNotificationEventLocal(newEvents)
                                }}
                                pipelineId={pipelineId}
                              />
                            </>
                          )}
                        </div>
                      </div>
                    ),
                    rgItemType: Type.CUSTOM,
                    onClick: async () => {
                      setIsCustomNotifications(true)
                      await submitChanges(customEvents, ownChangesOnly)
                    },
                    key: 'custom',
                  },
                  {
                    rgItemType: Type.SEPARATOR,
                    key: 'separator1',
                  },
                  {
                    template: (
                      <div>
                        <Icon className={styles.icon} name={'bell-crossed'} />
                        <Text>{'Unsubscribe'}</Text>
                      </div>
                    ),
                    rgItemType: Type.CUSTOM,
                    onClick: async () => {
                      setIsCustomNotifications(undefined)
                      await submitChanges(
                        DEFAULT_EVENTS.map(e => ({...e, enabled: false})),
                        false,
                      )
                    },
                    key: 'unsubscribe',
                  },
                ]}
                renderOptimization={false}
                onSelect={() => {}}
              />
              <div>
                <div className={cn(styles.footer, styles.popupLine)}>
                  <Text info size={'s'} className={styles.lineBreak}>
                    {
                      "You'll receive event notifications from \nall branches at your profile email address."
                    }
                  </Text>
                </div>
              </div>
            </>
          </Popup>
        </Dropdown>
      ) : (
        <SubscribeButton
          onClick={async () => {
            setIsCustomNotifications(false)
            await submitChanges(DEFAULT_EVENTS, true)
          }}
        />
      )}
    </>
  )
}
